// Brand images for the wallet card, inlined as data URIs.
//
// WalletWallet takes images either as an HTTPS URL it fetches, or inline like
// this. A URL would mean a card could only be built once the site is publicly
// reachable — which it is not in development — and would make card creation
// depend on our own uptime. Inlining removes both problems.
//
// Source: public/elsa-logo.jpg, resized to the dimensions the API documents.
// To change the logo, regenerate both sizes and replace the strings below.

/** Brand mark, top-left of the pass face. 160x160 PNG. */
export const ELSA_LOGO_DATA_URI =
  "data:image/png;base64,";

/** Icon in the iOS lock-screen notification when a pass updates. 120x120 PNG. */
export const ELSA_ICON_DATA_URI =
  "data:image/png;base64,";

export const ELSA_STRIP_DATA_URI ="data:image/png;base64,";
